begin;
create temp table fixture(actor uuid default gen_random_uuid(),other_actor uuid default gen_random_uuid(),viewer uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),other_candidate uuid default gen_random_uuid(),job uuid default gen_random_uuid());
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text,expected text default null) returns void language plpgsql as $$begin begin execute statement;exception when others then if expected is not null and sqlstate<>expected then raise exception 'FAILED wrong SQLSTATE %: %',sqlstate,name;end if;insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select id,id::text||'@review-test.invalid',now(),'authenticated','authenticated' from fixture, lateral unnest(array[actor,other_actor,viewer]) id;
insert into public.companies(id,name) select company,'Review A' from fixture union all select other_company,'Review B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'recruiter' from fixture union all select company,viewer,'viewer' from fixture union all select other_company,other_actor,'owner' from fixture;
insert into public.candidates(id,company_id,processing_status,dados_extraidos) select candidate,company,'concluido','{"nome_completo":"Ana IA","email":"ana@example.test","skills":["SQL"],"anos_experiencia_total":2,"experiencias":[],"formacao_academica":[],"idiomas":[],"certificacoes":[]}'::jsonb from fixture union all select other_candidate,other_company,'concluido','{}' from fixture;
update public.candidates set review_status='completed';
insert into public.jobs(id,company_id,titulo) select job,company,'Review job' from fixture;
update public.jobs set descricao='Descrição de teste com requisito SQL.',criteria='[{"kind":"skill","text":"SQL","min_years":null,"required":true,"weight":5,"source":null}]';
update public.jobs set approved_hash=private.job_hash(private.job_payload(titulo,descricao,categoria,criteria));
insert into public.candidate_scores(company_id,candidate_id,job_id,score,stale,candidate_version) select company,candidate,job,80,false,0 from fixture;
insert into public.job_reports(company_id,job_id,stale) select company,job,false from fixture;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.denied('direct editing cannot bypass review history','update public.candidates set localizacao=''Bypass''','42501');
select pg_temp.denied('cannot forge corrections or revision','update public.candidates set correcoes_rh=''{}'',review_version=99','42501');
select pg_temp.denied('cannot modify other company via RPC',$q$select public.save_candidate_review(other_company,other_candidate,0,'{"nome_completo":"Attack"}') from fixture$q$,'42501');
select pg_temp.denied('cannot cross candidate company',$q$select public.save_candidate_review(company,other_candidate,0,'{}') from fixture$q$,'42501');
select pg_temp.denied('unknown fields rejected',$q$select public.save_candidate_review(company,candidate,0,'{"confianca":1}') from fixture$q$,'22023');
select pg_temp.denied('bad email rejected',$q$select public.save_candidate_review(company,candidate,0,'{"email":"bad"}') from fixture$q$,'22023');
select pg_temp.denied('invalid dates rejected',$q$select public.save_candidate_review(company,candidate,0,'{"data_nascimento":"2025-02-31"}') from fixture$q$);
select pg_temp.denied('negative years rejected',$q$select public.save_candidate_review(company,candidate,0,'{"anos_experiencia_total":-1}') from fixture$q$,'22023');
select pg_temp.denied('reversed periods rejected',$q$select public.save_candidate_review(company,candidate,0,'{"experiencias":[{"inicio":"2024-12","fim":"2022-01"}]}') from fixture$q$,'22023');
select pg_temp.denied('future work rejected',$q$select public.save_candidate_review(company,candidate,0,'{"experiencias":[{"inicio":"2099-12","atual":true}]}') from fixture$q$,'22023');
select pg_temp.denied('completion needs explicit confirmation',$q$select public.save_candidate_review(company,candidate,0,'{}',true,false) from fixture$q$,'22023');
select public.save_candidate_review(company,candidate,0,'{"nome_completo":"Ana RH","telefone":"+55 11 99999-0000","localizacao":"Cidade digitada livremente","skills":["Python"],"experiencias":[{"empresa":"Empresa A","cargo":"Analista","inicio":"2020-01","fim":"2022-12","atual":false}],"formacao_academica":[{"curso":"Computação","instituicao":"Universidade","inicio":"2016","fim":"2019"}],"idiomas":["Português"],"certificacoes":["Certificação RH"],"anos_experiencia_total":3}') from fixture;
select pg_temp.ok('all editable fields saved',(select nome='Ana RH' and localizacao='Cidade digitada livremente' and skills=array['Python'] and anos_experiencia=3 and dados_efetivos->'formacao_academica'->0->>'curso'='Computação' and dados_efetivos->'idiomas'='["Português"]' and dados_efetivos->'certificacoes'='["Certificação RH"]' from public.candidates));
select pg_temp.ok('AI source remains unchanged',(select dados_extraidos->>'nome_completo'='Ana IA' and dados_extraidos->'skills'='["SQL"]' from public.candidates));
select pg_temp.ok('review version advances once',(select review_version=1 and data_version=1 and review_status='draft' from public.candidates));
select pg_temp.ok('audit records actor and old/new fields',(select actor_id=(select actor from fixture) and changes->'nome_completo'->>'antes'='Ana IA' and changes->'nome_completo'->>'depois'='Ana RH' and created_at is not null from public.candidate_revisions));
select pg_temp.ok('existing assessment retained but marked stale',(select count(*)=1 and bool_and(stale) from public.candidate_scores));
select pg_temp.ok('reports marked stale',(select bool_and(stale) from public.job_reports));
select pg_temp.denied('stale editor cannot overwrite new data',$q$select public.save_candidate_review(company,candidate,0,'{"nome_completo":"Lost update"}') from fixture$q$,'40001');
select pg_temp.denied('clients cannot forge history','delete from public.candidate_revisions','42501');
select public.save_candidate_review(company,candidate,1,'{"email":null}',true,true) from fixture;
select pg_temp.ok('completion records reviewer and time',(select review_status='completed' and reviewed_by=(select actor from fixture) and reviewed_at is not null and correcoes_rh ? 'certificacoes' and correcoes_rh->'email'='null'::jsonb from public.candidates));
reset role;
set local role service_role;
select public.save_candidate_extraction(actor,company,candidate,'{"nome_completo":"Nome reprocessado","email":"invented@example.test","telefone":"11111111111","skills":["Rust"],"anos_experiencia_total":99,"experiencias":[],"formacao_academica":[],"idiomas":[],"certificacoes":[]}','concluido') from fixture;
select pg_temp.ok('reprocessing cannot overwrite human correction or confirmed absence',(select nome='Ana RH' and email is null and skills=array['Python'] and anos_experiencia=3 and dados_efetivos->'experiencias'->0->>'cargo'='Analista' from public.candidates where id=(select candidate from fixture)));
select pg_temp.ok('new AI remains separately accessible and review reopened',(select dados_extraidos->>'nome_completo'='Nome reprocessado' and review_status='pending' and review_version=3 from public.candidates where id=(select candidate from fixture)));
select pg_temp.denied('ranking calculated against older data cannot be published',$q$select public.replace_job_scores_v2(actor,company,job,(select version from public.jobs where id=job),(select approved_hash from public.jobs where id=job),jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',99,'candidate_version',0))) from fixture$q$,'40001');
update public.candidates set review_status='completed' where id=(select candidate from fixture);
select public.replace_job_scores_v2(actor,company,job,(select version from public.jobs where id=job),(select approved_hash from public.jobs where id=job),jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',90,'candidate_version',c.data_version,'detalhes_matching','{}'::jsonb))) from fixture join public.candidates c on c.id=fixture.candidate;
select pg_temp.ok('fresh evaluation clears stale state',(select not stale from public.candidate_scores));
reset role;
select set_config('request.jwt.claims',json_build_object('sub',viewer,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('viewer may consult history',(select count(*)=2 from public.candidate_revisions));
select pg_temp.denied('viewer cannot review',$q$select public.save_candidate_review(company,candidate,3,'{}',true,true) from fixture$q$,'42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',other_actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('other company cannot read review history',(select count(*)=0 from public.candidate_revisions));
reset role;
delete from public.company_members where user_id=(select actor from fixture);
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.denied('revoked actor cannot save even with old JWT',$q$select public.save_candidate_review(company,candidate,3,'{}',true,true) from fixture$q$,'42501');
select pg_temp.ok('revoked actor cannot read history',(select count(*)=0 from public.candidate_revisions));
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) as results from results;
rollback;
